import "server-only";
import aave from "../data/aave-v3.json";
import compound from "../data/compound-v3.json";
import morpho from "../data/morpho.json";
import uniswap from "../data/uniswap-v3.json";
import type { Protocol } from "../types";
import { summarize } from "../utils/protocol";

// Static fixtures generated by foundry/luora-protocol.mjs; nothing is fetched at runtime.
const ALL = [uniswap, aave, morpho, compound] as unknown as Protocol[];

export const protocolIds = () => ALL.map((p) => p.id);
export const protocolSummaries = () => ALL.map(summarize);
export const loadProtocol = (id: string) => ALL.find((p) => p.id === id);
